                                  "type": "Action.Submit",
                                  "title": "Approve",
                                  "data": {
                                      "action": "approve"
                                  },
                                  "style": "positive"
                              }
                          ]
                      }
                  ],
                  "width": "stretch"
              },
              {
                  "type": "Column",
                  "items": [
                      {
                          "type": "ActionSet",
                          "actions": [
                              {
                                  "type": "Action.Submit",
                                  "title": "Reply",
                                  "data": {
                                      "action": "reply"
                                  }
                              }
                          ]
                      }
                  ],
                  "width": "stretch"
              },
              {
                  "type": "Column",
                  "items": [
                      {
                          "type": "ActionSet",
                          "actions": [
                              {
                                  "type": "Action.Submit",
                                  "title": "Change",
                                  "data": {
                                      "action": "change"
                                  }
                              }
                          ]
                      }
                  ],
                  "width": "stretch"
              },
              {
                  "type": "Column",
                  "items": [
                      {
                          "type": "ActionSet",
                          "actions": [
                              {
                                  "type": "Action.Submit",
                                  "title": "Reject",
                                  "data": {
                                      "action": "reject"
                                  },
                                  "style": "destructive"
                              }
                          ]
                      }
                  ],
                  "width": "stretch"
              }
          ]
      }
  ],
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
    "version": "1.4"
}

